// Asks Administrate for every contact with a conflict between today and today + WINDOW_DAYS.
// Administrate works the conflicts out itself: sessions that overlap and sessions during an absence.
const cfgObj = $('Config').first().json;
const daysNum = Math.max(1, Number(cfgObj.WINDOW_DAYS) || 30);
const fromStr = $now.toISODate();
const toStr = $now.plus({ days: daysNum }).toISODate();
const queryStr = 'query ReadConflicts($from: Date!, $to: Date!) { contactConflicts(rangeStartDate: $from, rangeEndDate: $to) { conflictCount contact { id emailAddress personalName { firstName lastName } } sessions { id code title start end eventId conflicts { bookingType title start end unconfirmed } } } }';
return [{ json: { from: fromStr, to: toStr, body: { query: queryStr, variables: { from: fromStr, to: toStr } } } }];

// Groups the conflicts by instructor and by date and builds one HTML email.
// Returns nothing when there is no conflict, so no email is sent.
const cfgObj = $('Config').first().json;
const rangeObj = $('Build Query').first().json;
const resObj = $input.first().json || {};
if (resObj.errors || !resObj.data || !Array.isArray(resObj.data.contactConflicts)) {
  throw new Error('Reading conflicts failed: ' + JSON.stringify(resObj.errors || resObj).slice(0, 500));
}
const escFn = function (vAny) { return String(vAny === null || vAny === undefined ? '' : vAny).split('&').join('&amp;').split('<').join('&lt;').split('>').join('&gt;').split('"').join('&quot;'); };
const whenFn = function (sStr) { const dObj = DateTime.fromISO(String(sStr || ''), { setZone: true }); return dObj.isValid ? dObj : null; };
// Shows the full date, or only the times when it falls on the same day as refStr.
const spanFn = function (aStr, bStr, refStr) {
  const aObj = whenFn(aStr); const bObj = whenFn(bStr); const rObj = refStr ? whenFn(refStr) : null;
  if (!aObj) { return escFn(aStr); }
  const endStr = bObj ? (bObj.hasSame(aObj, 'day') ? bObj.toFormat('HH:mm') : bObj.toFormat('ccc d LLL HH:mm')) : '';
  const startStr = rObj && rObj.hasSame(aObj, 'day') ? aObj.toFormat('HH:mm') : aObj.toFormat('ccc d LLL yyyy, HH:mm');
  return startStr + (endStr ? ' to ' + endStr : '');
};
// Event links use the event number, which is the part after ':' in the decoded API ID.
const eventNumberFn = function (idStr) {
  try { const decodedStr = Buffer.from(String(idStr || ''), 'base64').toString('utf8'); return decodedStr.split(':')[1] || idStr; } catch (errAny) { return idStr; }
};
const includeUnconfirmedBool = cfgObj.INCLUDE_UNCONFIRMED !== false;
const urlTemplateStr = String(cfgObj.EVENT_URL_TEMPLATE || '');
const peopleAry = [];
let totalNum = 0;
for (const cObj of resObj.data.contactConflicts) {
  const nameObj = (cObj.contact || {}).personalName || {};
  const nameStr = ((nameObj.firstName || '') + ' ' + (nameObj.lastName || '')).trim() || ((cObj.contact || {}).emailAddress || 'Unknown contact');
  const rowsAry = [];
  for (const sObj of (cObj.sessions || [])) {
    const seenObj = {};
    const withAry = [];
    for (const kObj of (sObj.conflicts || [])) {
      if (kObj.unconfirmed && !includeUnconfirmedBool) { continue; }
      const keyStr = [kObj.bookingType, kObj.title, kObj.start, kObj.end].join('|');
      if (seenObj[keyStr]) { continue; }
      seenObj[keyStr] = true;
      withAry.push(kObj);
    }
    if (withAry.length === 0) { continue; }
    rowsAry.push({ session: sObj, conflicts: withAry, sortKey: String(sObj.start || '') });
  }
  if (rowsAry.length === 0) { continue; }
  rowsAry.sort(function (aObj, bObj) { return aObj.sortKey < bObj.sortKey ? -1 : (aObj.sortKey > bObj.sortKey ? 1 : 0); });
  totalNum += rowsAry.length;
  peopleAry.push({ name: nameStr, rows: rowsAry, first: rowsAry[0].sortKey });
}
if (peopleAry.length === 0) { return []; }
peopleAry.sort(function (aObj, bObj) { return aObj.first < bObj.first ? -1 : (aObj.first > bObj.first ? 1 : 0); });
const blockAry = peopleAry.map(function (pObj) {
  const trsStr = pObj.rows.map(function (rObj) {
    const sObj = rObj.session;
    const linkStr = urlTemplateStr && urlTemplateStr.indexOf('YOUR-INSTANCE') < 0 ? urlTemplateStr.split('{id}').join(encodeURIComponent(eventNumberFn(sObj.eventId))) : '';
    const labelStr = escFn(sObj.code) + ' &middot; ' + escFn(sObj.title);
    const whatStr = rObj.conflicts.map(function (kObj) {
      const kindStr = kObj.bookingType === 'absence' ? 'Absence' : (kObj.bookingType === 'session' ? 'Another session' : escFn(kObj.bookingType));
      return '<div style="margin:2px 0;">' + kindStr + ': <strong>' + escFn(kObj.title || 'untitled') + '</strong> (' + spanFn(kObj.start, kObj.end, sObj.start) + ')' + (kObj.unconfirmed ? ' <span style="color:#8A5A00;">unconfirmed</span>' : '') + '</div>';
    }).join('');
    return '<tr><td style="padding:10px 12px;border-top:1px solid #E6EAF0;vertical-align:top;white-space:nowrap;font-size:13px;color:#16202B;">' + spanFn(sObj.start, sObj.end) + '</td><td style="padding:10px 12px;border-top:1px solid #E6EAF0;vertical-align:top;font-size:13px;color:#16202B;">' + (linkStr ? '<a href="' + escFn(linkStr) + '" style="color:' + escFn(cfgObj.BRAND_COLOUR) + ';">' + labelStr + '</a>' : labelStr) + '<div style="margin-top:4px;color:#5A6472;">' + whatStr + '</div></td></tr>';
  }).join('');
  return '<h3 style="margin:24px 0 6px;font-size:15px;color:#16202B;">' + escFn(pObj.name) + ' <span style="font-weight:normal;color:#5A6472;">(' + pObj.rows.length + ' session' + (pObj.rows.length > 1 ? 's' : '') + ')</span></h3><table width="100%" cellpadding="0" cellspacing="0" style="border-collapse:collapse;">' + trsStr + '</table>';
}).join('');
const fromLabel = DateTime.fromISO(rangeObj.from).toFormat('d LLL yyyy');
const toLabel = DateTime.fromISO(rangeObj.to).toFormat('d LLL yyyy');
const htmlStr = '<div style="font-family:Arial,Helvetica,sans-serif;background:#F4F6F8;padding:24px;"><table width="680" cellpadding="0" cellspacing="0" style="background:#FFFFFF;border-radius:8px;"><tr><td style="background:' + escFn(cfgObj.BRAND_COLOUR) + ';padding:18px 24px;color:#FFFFFF;font-size:18px;font-weight:bold;">' + escFn(cfgObj.BRAND_NAME) + '</td></tr><tr><td style="padding:24px;"><p style="margin:0 0 4px;font-size:16px;color:#16202B;"><strong>' + totalNum + ' session' + (totalNum > 1 ? 's' : '') + ' with an instructor conflict</strong> across ' + peopleAry.length + ' instructor' + (peopleAry.length > 1 ? 's' : '') + '</p><p style="margin:0;font-size:13px;color:#5A6472;">From ' + fromLabel + ' to ' + toLabel + '. Each line is a session the instructor is booked on while also booked elsewhere or recorded as absent.</p>' + blockAry + '</td></tr></table></div>';
const subjectStr = (cfgObj.EMAIL_SUBJECT_PREFIX || 'Instructor availability conflicts') + ': ' + totalNum + ' session' + (totalNum > 1 ? 's' : '') + ', ' + peopleAry.length + ' instructor' + (peopleAry.length > 1 ? 's' : '');
return [{ json: { subject: subjectStr, html: htmlStr, sessions: totalNum, instructors: peopleAry.map(function (pObj) { return pObj.name; }) } }];

// The email goes through Administrate, so each recipient must be an Administrate contact.
const cfgObj = $('Config').first().json;
const emailsAry = Array.from(new Set(String(cfgObj.RECIPIENT_EMAILS || '').split(',').map(function (eStr) { return eStr.trim().toLowerCase(); }).filter(Boolean)));
if (emailsAry.length === 0) { throw new Error('RECIPIENT_EMAILS is empty in the Config node.'); }
const partsAry = emailsAry.map(function (eStr, iNum) { return 'r' + iNum + ': contacts(first: 2, filters: [{ field: emailAddress, operation: eq, value: ' + JSON.stringify(eStr) + ' }]) { edges { node { id emailAddress } } }'; });
return [{ json: { emails: emailsAry, body: { query: 'query FindRecipients { ' + partsAry.join(' ') + ' }' } } }];

// One item per recipient contact. Stops with a clear message, before any email is sent, if an
// address is not a contact or matches several contacts.
const emailsAry = $('Build Recipient Query').first().json.emails;
const digestObj = $('Build Digest').first().json;
const resObj = $input.first().json || {};
if (resObj.errors || !resObj.data) { throw new Error('Looking up recipients failed: ' + JSON.stringify(resObj.errors || resObj).slice(0, 300)); }
const missingAry = [];
const sharedAry = [];
const outAry = [];
emailsAry.forEach(function (eStr, iNum) {
  const edgesAry = ((resObj.data['r' + iNum] || {}).edges) || [];
  if (edgesAry.length === 0) { missingAry.push(eStr); return; }
  if (edgesAry.length > 1) { sharedAry.push(eStr); return; }
  outAry.push({ json: { contactId: edgesAry[0].node.id, email: eStr, subject: digestObj.subject, html: digestObj.html } });
});
if (missingAry.length > 0) { throw new Error('No Administrate contact found for: ' + missingAry.join(', ') + '. Each recipient needs a contact record.'); }
if (sharedAry.length > 0) { throw new Error('Several Administrate contacts share: ' + sharedAry.join(', ') + '. Merge or correct the duplicate contacts so each recipient matches one contact.'); }
return outAry;

const recObj = $('Resolve Recipients').item.json;
const resObj = $json || {};
const sendObj = ((resObj.data || {}).contactAdhocEmails || {}).sendContactAdhocEmail;
const errsAry = (resObj.errors || []).concat((sendObj && sendObj.errors) || []);
if (!sendObj || errsAry.length > 0) {
  throw new Error('The digest could not be sent to ' + recObj.email + ': ' + (errsAry.map(function (eObj) { return eObj.message; }).join('; ') || 'missing response'));
}
return { json: { sentTo: recObj.email } };
